1	use std::collections::BTreeMap;
2	
3	/// One damaged item reported in an incident.
4	pub struct Damage {
5	    pub item_type: String,
6	    pub amount: i64,
7	}
8	
9	/// A damage report filed against an existing policy.
10	pub struct Incident {
11	    pub damages: Vec<Damage>,
12	}
13	
14	/// Why the MHPCO refuses to settle a claim at all.
15	#[derive(Debug)]
16	pub enum ClaimError {
17	    /// The policy covers no item of this type at all.
18	    ItemNotInsured { item_type: String },
19	    /// More damages of this item type were reported than the policy covers.
20	    MoreDamagesThanInsuredItems { item_type: String },
21	}
22	
23	impl std::fmt::Display for ClaimError {
24	    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
25	        match self {
26	            Self::ItemNotInsured { item_type } => {
27	                write!(formatter, "the damaged {item_type} is not insured by this policy")
28	            }
29	            Self::MoreDamagesThanInsuredItems { item_type } => write!(
30	                formatter,
31	                "more {item_type} damages were reported than the policy insures"
32	            ),
33	        }
34	    }
35	}
