37	/// What the MHPCO settles on a claim: the payout and the cap left on the
38	/// policy afterwards.
39	#[derive(Debug)]
40	pub struct ClaimResult {
41	    pub payout: u64,
42	    pub remaining_cap: u64,
43	}
44	
45	/// The single customer a scenario is quoted for.
46	pub struct Customer {
47	    pub years_with_mhpco: u32,
48	}
49	
50	pub struct Item {
51	    pub item_type: String,
52	    pub material: String,
53	    pub enchantment: u32,
54	    pub cursed: bool,
55	}
56	
57	const PROCESSING_FEE: u64 = 5;
58	const DEDUCTIBLE_PER_DAMAGE: u64 = 100;
59	const CAP_MULTIPLE_OF_INSURANCE_SUM: u64 = 2;
60	const HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL: u32 = 8;
61	const HALF_REIMBURSEMENT_PERCENT: u64 = 50;
62	
63	const SWORD_INSURANCE_VALUE: u64 = 1000;
64	const AMULET_INSURANCE_VALUE: u64 = 600;
65	const COMPONENT_INSURANCE_VALUE: u64 = 250;
66	const SWORD_BASE_PREMIUM: u64 = 100;
67	const AMULET_BASE_PREMIUM: u64 = 60;
68	const STAFF_BASE_PREMIUM: u64 = 80;
69	const POTION_BASE_PREMIUM: u64 = 40;
70	const COMPONENT_BASE_PREMIUM: u64 = 25;
71	const COMPONENT_BLOCK_BASE_PREMIUM: u64 = 60;
72	const COMPONENT_BLOCK_SIZE: usize = 3;
73	const CURSE_SURCHARGE_PERCENT: u64 = 50;
74	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT: u64 = 30;
75	const HIGH_ENCHANTMENT_LEVEL: u32 = 5;
76	const FIRST_INSURANCE_SURCHARGE_PERCENT: u64 = 10;
77	const LOYALTY_DISCOUNT_PERCENT: u64 = 20;
78	const LOYALTY_YEARS: u32 = 2;
79	const FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT: u64 = 15;
80	
81	/// Components, such as runes and moonstones, are the parts the MHPCO insures
82	/// alongside main items and the only items the building-block offer covers.
83	fn is_component(item: &Item) -> bool {
84	    matches!(item.item_type.as_str(), "rune" | "moonstone")
85	}
86	
87	/// The MHPCO price list: the base premium the catalogue lists for one item.
88	fn base_premium(item: &Item) -> u64 {
89	    if is_component(item) {
90	        return COMPONENT_BASE_PREMIUM;
91	    }
92	    match item.item_type.as_str() {
93	        "amulet" => AMULET_BASE_PREMIUM,
94	        "staff" => STAFF_BASE_PREMIUM,
95	        "potion" => POTION_BASE_PREMIUM,
96	        _ => SWORD_BASE_PREMIUM,
97	    }
98	}
99	
100	/// The building-block offer is reserved for a group of exactly 3 alike
101	/// components; a larger group does not qualify, it is priced per component.
102	fn qualifies_as_building_block(alike_component_count: usize) -> bool {
103	    alike_component_count == COMPONENT_BLOCK_SIZE
104	}
105	
106	/// The price the MHPCO charges for one group of alike components: the
107	/// building-block offer when the group qualifies, otherwise per component.
108	fn component_group_base_premium(count: usize) -> u64 {
109	    if qualifies_as_building_block(count) {
110	        COMPONENT_BLOCK_BASE_PREMIUM
111	    } else {
112	        count as u64 * COMPONENT_BASE_PREMIUM
113	    }
114	}
115	
116	/// How many entries of each catalogue type a list holds.
117	fn count_by_item_type<'a>(
118	    item_types: impl Iterator<Item = &'a str>,
119	) -> BTreeMap<&'a str, usize> {
120	    let mut counts: BTreeMap<&str, usize> = BTreeMap::new();
121	    for item_type in item_types {
122	        *counts.entry(item_type).or_insert(0) += 1;
123	    }
124	    counts
125	}
126	
127	/// Two components are "alike" when they share this key. For the MHPCO,
128	/// alike means the very same catalogue type: a rune and a moonstone are
129	/// never alike, so mixed component types form no building block.
130	fn alike_group_key(item: &Item) -> &str {
131	    &item.item_type
132	}
133	
134	/// The policy base premium: the sum of all insured items' base premiums,
135	/// with alike components priced per group so a block can be recognised.
136	fn policy_base_premium(items: &[Item]) -> u64 {
137	    let mut main_items_total = 0;
138	    let mut alike_component_counts: BTreeMap<&str, usize> = BTreeMap::new();
139	    for item in items {
140	        if is_component(item) {
141	            *alike_component_counts.entry(alike_group_key(item)).or_insert(0) += 1;
142	        } else {
143	            main_items_total += base_premium(item);
144	        }
145	    }
146	
147	    main_items_total
148	        + alike_component_counts
149	            .values()
150	            .map(|count| component_group_base_premium(*count))
151	            .sum::<u64>()
152	}
153	
154	/// Who owes an amount, which is what decides the direction the MHPCO rounds it.
155	#[derive(Clone, Copy)]
156	enum Debtor {
157	    Customer,
158	    Mhpco,
159	}
160	
161	/// Every amount is rounded to whole G in the MHPCO's favor. That one rule
162	/// settles the direction by itself once it is known who owes whom: an amount
163	/// the customer owes is rounded up, an amount the office owes is rounded down.
164	/// Intermediate amounts stay fractional; only the final amount is rounded.
165	fn rounded_in_mhpco_favor(amount: f64, owed_by: Debtor) -> u64 {
166	    match owed_by {
167	        Debtor::Customer => amount.ceil() as u64,
168	        Debtor::Mhpco => amount.floor() as u64,
169	    }
170	}
171	
172	/// A policy-wide modifier is measured against the policy base premium, the
173	/// sum of all item base premiums, never against a single item.
174	fn percent_of_policy_base(policy_base_premium: f64, percent: u64) -> f64 {
175	    policy_base_premium * percent as f64 / 100.0
176	}
177	
178	/// Every item in a quote is treated as a first insurance, so the initial
179	/// assessment surcharge is charged on the whole policy base premium.
180	fn first_insurance_surcharge(policy_base_premium: f64) -> f64 {
181	    percent_of_policy_base(policy_base_premium, FIRST_INSURANCE_SURCHARGE_PERCENT)
182	}
183	
184	/// The MHPCO charges a high-enchantment risk surcharge on items it considers
185	/// highly enchanted. This is the premium-side threshold; the claim-side
186	/// reimbursement clause judges enchantment by its own, stricter threshold.
187	fn is_highly_enchanted(item: &Item) -> bool {
188	    item.enchantment >= HIGH_ENCHANTMENT_LEVEL
189	}
190	
191	/// An item-specific risk surcharge is charged on the base premium of the
192	/// affected item, never on the policy total.
193	fn risk_surcharge_on_base_premium(item: &Item, surcharge_percent: u64) -> f64 {
194	    base_premium(item) as f64 * surcharge_percent as f64 / 100.0
195	}
196	
197	/// The risk surcharge one item carries. Risks the MHPCO recognises stack: an
198	/// item that brings two of them is surcharged for each.
199	fn item_risk_surcharge(item: &Item) -> f64 {
200	    let mut surcharge = 0.0;
201	    if item.cursed {
202	        surcharge += risk_surcharge_on_base_premium(item, CURSE_SURCHARGE_PERCENT);
203	    }
204	    if is_highly_enchanted(item) {
205	        surcharge += risk_surcharge_on_base_premium(item, HIGH_ENCHANTMENT_SURCHARGE_PERCENT);
206	    }
207	    surcharge
208	}
209	
210	/// Item-specific modifiers apply to the base premium of the affected item,
211	/// never to the policy total, so the policy owes the sum of the items' own
212	/// risk surcharges.
213	fn item_risk_surcharges(items: &[Item]) -> f64 {
214	    items.iter().map(item_risk_surcharge).sum()
215	}
216	
217	/// A long-standing customer, with at least two years of business with the
218	/// MHPCO, has earned the loyalty discount.
219	fn is_long_standing(customer: &Customer) -> bool {
220	    customer.years_with_mhpco >= LOYALTY_YEARS
221	}
222	
223	/// The loyalty discount is a policy-wide modifier, so it is measured against
224	/// the policy base premium.
225	fn loyalty_discount(customer: &Customer, policy_base_premium: f64) -> f64 {
226	    if is_long_standing(customer) {
227	        percent_of_policy_base(policy_base_premium, LOYALTY_DISCOUNT_PERCENT)
228	    } else {
229	        0.0
230	    }
231	}
232	
233	/// A contract is a follow-up when the customer already holds at least one
234	/// other contract with the MHPCO; the customer's very first is not.
235	fn is_follow_up_contract(contracts_already_held: u32) -> bool {
236	    contracts_already_held > 0
237	}
238	
239	/// Every contract after the customer's first earns the follow-up discount. It
240	/// is a policy-wide modifier, so it is measured against the policy base premium.
241	fn follow_up_contract_discount(contracts_already_held: u32, policy_base_premium: f64) -> f64 {
242	    if is_follow_up_contract(contracts_already_held) {
243	        percent_of_policy_base(policy_base_premium, FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT)
244	    } else {
245	        0.0
246	    }
247	}
248	
249	/// What the customer's standing with the MHPCO adds to or takes off the policy
250	/// base premium: the net of every policy-wide surcharge and discount. Positive
251	/// amounts raise the premium, negative amounts lower it.
252	fn policy_wide_modifiers(
253	    customer: &Customer,
254	    contracts_already_held: u32,
255	    policy_base_premium: f64,
256	) -> f64 {
257	    first_insurance_surcharge(policy_base_premium)
258	        - loyalty_discount(customer, policy_base_premium)
259	        - follow_up_contract_discount(contracts_already_held, policy_base_premium)
260	}
261	
262	/// The premium the policy earns before the processing fee: the policy base
263	/// premium, plus what the items' own risks cost, plus what the customer's
264	/// standing adjusts.
265	fn modified_policy_premium(
266	    customer: &Customer,
267	    contracts_already_held: u32,
268	    items: &[Item],
269	) -> f64 {
270	    let policy_base_premium = policy_base_premium(items) as f64;
271	    policy_base_premium
272	        + item_risk_surcharges(items)
273	        + policy_wide_modifiers(customer, contracts_already_held, policy_base_premium)
274	}
275	
276	/// The MHPCO adds its processing fee to every premium at the very end, after
277	/// every surcharge and discount has been settled.
278	pub fn quote_premium(
279	    customer: &Customer,
280	    contracts_already_held: u32,
281	    items: &[Item],
282	) -> u64 {
283	    rounded_in_mhpco_favor(
284	        modified_policy_premium(customer, contracts_already_held, items) + PROCESSING_FEE as f64,
285	        Debtor::Customer,
286	    )
287	}
288	
289	/// Damage to a very highly enchanted item is reimbursed at only half the
290	/// damage amount. This claim-side threshold is deliberately stricter than, and
291	/// separate from, the premium-side high-enchantment risk surcharge: an item can
292	/// be enchanted enough to cost more to insure yet not enough to be halved.
293	fn is_reimbursed_by_half(item: &Item) -> bool {
294	    item.enchantment >= HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL
295	}
296	
297	/// How much of a reported damage the MHPCO's reimbursement clauses cover,
298	/// before the deductible is taken off. Full reimbursement is the MHPCO's
299	/// standing position: it is both what an item with no clause receives and what
300	/// the dragon-material clause prescribes, so that clause asks for no share of
301	/// its own. Only the halving clause departs from full reimbursement, and it
302	/// wins wherever it applies.
303	fn covered_damage(damaged_item: &Item, damage: &Damage) -> f64 {
304	    if is_reimbursed_by_half(damaged_item) {
305	        damage.amount as f64 * HALF_REIMBURSEMENT_PERCENT as f64 / 100.0
306	    } else {
307	        damage.amount as f64
308	    }
309	}
310	
311	/// The deductible applies per damage event, after the reimbursement clauses.
312	fn reimbursement_for(damaged_item: &Item, damage: &Damage) -> f64 {
313	    (covered_damage(damaged_item, damage) - DEDUCTIBLE_PER_DAMAGE as f64).max(0.0)
314	}
315	
316	/// Which insured item a reported damage refers to. A damage names only a
317	/// catalogue type, so the policy is searched for an item of that type; the
318	/// reimbursement clauses are judged against the item found here, not the report.
319	fn insured_item_for<'a>(items: &'a [Item], damage: &Damage) -> &'a Item {
320	    items
321	        .iter()
322	        .find(|item| item.item_type == damage.item_type)
323	        .expect("the damaged item is insured by this policy")
324	}
325	
326	/// What the MHPCO owes for an incident filed against a policy: the sum of the
327	/// reimbursements its damages earn, rounded in the office's favor at the end.
328	pub fn claim_payout(items: &[Item], incident: &Incident) -> u64 {
329	    let total: f64 = incident
330	        .damages
331	        .iter()
332	        .map(|damage| reimbursement_for(insured_item_for(items, damage), damage))
333	        .sum();
334	    rounded_in_mhpco_favor(total, Debtor::Mhpco)
335	}
336	
337	/// The MHPCO price list also lists what each item is insured for.
338	fn insurance_value(item: &Item) -> u64 {
339	    if is_component(item) {
340	        return COMPONENT_INSURANCE_VALUE;
341	    }
342	    match item.item_type.as_str() {
343	        "amulet" => AMULET_INSURANCE_VALUE,
344	        _ => SWORD_INSURANCE_VALUE,
345	    }
346	}
347	
348	/// The insurance sum of a policy is the sum of its items' insurance values.
349	fn insurance_sum(items: &[Item]) -> u64 {
350	    items.iter().map(insurance_value).sum()
351	}
352	
353	/// The total payout per policy is capped at twice the insurance sum.
354	fn policy_cap(items: &[Item]) -> u64 {
355	    CAP_MULTIPLE_OF_INSURANCE_SUM * insurance_sum(items)
356	}
357	
358	/// How the cap limits one settlement: the MHPCO pays what the incident earned,
359	/// but never more than the cap the policy has left, and reports the cap that
360	/// survives the payout.
361	fn settled_within_cap(earned: u64, available_cap: u64) -> ClaimResult {
362	    let payout = earned.min(available_cap);
363	    ClaimResult {
364	        payout,
365	        remaining_cap: available_cap - payout,
366	    }
367	}
368	
369	/// How much of its cap a policy still has to pay out with, once earlier claims
370	/// have drawn on it. A cap can be drawn down until it is exhausted, and an
371	/// exhausted cap is simply nothing left, never a debt the policy owes back.
372	fn cap_remaining_on(items: &[Item], cap_already_consumed: u64) -> u64 {
373	    policy_cap(items).saturating_sub(cap_already_consumed)
374	}
375	
376	/// Every reported damage must be covered by an insured item of its own: the
377	/// MHPCO refuses a claim that reports more damages of a type than it insures.
378	/// The office compares the damages it was sent against the policy type by type,
379	/// so a type damaged twice needs two insured items of that type to stand.
380	fn check_every_damage_has_an_insured_item(
381	    items: &[Item],
382	    incident: &Incident,
383	) -> Result<(), ClaimError> {
384	    let insured = count_by_item_type(items.iter().map(|item| item.item_type.as_str()));
385	    for (item_type, reported) in
386	        count_by_item_type(incident.damages.iter().map(|damage| damage.item_type.as_str()))
387	    {
388	        let insured_of_that_type = insured.get(item_type).copied().unwrap_or(0);
389	        if insured_of_that_type == 0 {
390	            return Err(ClaimError::ItemNotInsured {
391	                item_type: item_type.to_string(),
392	            });
393	        }
394	        if reported > insured_of_that_type {
395	            return Err(ClaimError::MoreDamagesThanInsuredItems {
396	                item_type: item_type.to_string(),
397	            });
398	        }
399	    }
400	    Ok(())
401	}
402	
403	/// What the MHPCO settles on an incident filed against a policy: what the
404	/// incident earns, limited by the cap the policy has left. The office first
405	/// satisfies itself that the claim is admissible at all; an inadmissible claim
406	/// is refused whole, and nothing is paid out on it.
407	pub fn claim(
408	    items: &[Item],
409	    incident: &Incident,
410	    cap_already_consumed: u64,
411	) -> Result<ClaimResult, ClaimError> {
412	    check_every_damage_has_an_insured_item(items, incident)?;
413	    Ok(settled_within_cap(
414	        claim_payout(items, incident),
415	        cap_remaining_on(items, cap_already_consumed),
416	    ))
417	}
